def base64_decode_and_clean(ciphertexts):
    decoded = []
    for ct in ciphertexts:
        clean_ct = ct.replace("\n", "")  # Strip newlines
        if len(clean_ct) % 4:  # Add padding if needed
            clean_ct += "=" * (4 - len(clean_ct) % 4)
        decoded.append(base64.b64decode(clean_ct))
    return decoded

